  glow += pulseBand(wD1a, uv.y, t, 0.3 * pulseSpeed, 0.1, wavePulseStrength);
  glow += pulseBand(wD1b, uv.y, t, 0.22 * pulseSpeed, 0.6, wavePulseStrength);
  glow += pulseBand(wD2a, uv.y, t, 0.28 * pulseSpeed, 0.2, wavePulseStrength);
